/**
 * The text of the generated files. Nothing here reads the clock, the machine
 * or the commit: a commit in the text would change every target's key.
 *
 * @since 0.1.0
 */

import * as Result from "effect/Result"
import type { Inventory, Toolchain } from "../contract/Inventory.ts"
import type { Failure, GeneratedFile, GenerateOptions } from "../contract/Parts.ts"
import { path as targetMapPath, type TargetMap } from "../contract/TargetMap.ts"
import { markerDirectory, repositoryLabel, type StepPlan, type StepTarget, workflowPath } from "./Steps.ts"

export { workflowPath }

/**
 * The file holding every generated target. It is the root package because a
 * glob sees only its own package, and a step can read any file. A directory
 * with its own `PACKAGE.ts` is another package, which the root glob skips.
 *
 * @category constants
 * @since 0.1.0
 */
export const packagePath = "PACKAGE.ts"

/**
 * The generated workspace declaration.
 *
 * @category constants
 * @since 0.1.0
 */
export const workspacePath = ".smithers/WORKSPACE.ts"

/**
 * What the original CI does that the targets do not. Kept out of `PACKAGE.ts`,
 * which has a size limit.
 *
 * @category constants
 * @since 0.1.0
 */
export const notesPath = ".smithers/ci/NOT-REPRODUCED.md"

const generated = "Generated by smithers-ci. Do not edit."

// Above this many targets they share one file group. Each target otherwise
// lists every file in the plan, which outgrows a string on a large repository.
const sharedInputsAbove = 32

// Smithers refuses a larger PACKAGE.ts.
const maximumPackageBytes = 1024 * 1024

// GitHub stops a job after six hours; the build's own default is 30 minutes.
const stepTimeout = "6h"

const setupActions: ReadonlyMap<string, { readonly uses: string; readonly input: string }> = new Map([
  ["bun", { uses: "oven-sh/setup-bun@v2", input: "bun-version" }],
  ["go", { uses: "actions/setup-go@v5", input: "go-version" }],
  ["just", { uses: "extractions/setup-just@v3", input: "just-version" }],
  ["node", { uses: "actions/setup-node@v4", input: "node-version" }],
  ["pnpm", { uses: "pnpm/action-setup@v4", input: "version" }],
  ["python", { uses: "actions/setup-python@v5", input: "python-version" }],
  ["rust", { uses: "dtolnay/rust-toolchain@stable", input: "toolchain" }],
  ["zig", { uses: "mlugg/setup-zig@v2", input: "version" }]
])

const text = (value: string): string => JSON.stringify(value)

const comment = (value: string): string => `// ${value.replace(/[\r\n\u2028\u2029]+/g, " ")}`

const yamlComment = (value: string): string => `# ${value.replace(/[\r\n\u2028\u2029]+/g, " ")}`

const workspaceName = (repository: string): string => {
  const name = repository.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[^A-Za-z0-9]+/, "")
  return name === "" ? "repository" : name
}

const renderWorkspace = (inventory: Inventory): string =>
  [
    comment(generated),
    `import { Smithers as S } from "@smthrs/targets"`,
    ``,
    `export const Workspace = S.Workspace(${text(workspaceName(inventory.repository))}, {`,
    `  repository: ${text(inventory.repository)},`,
    `  cache: S.Cache({ directory: ".flows" }),`,
    `  host: S.Host({ bins: ["sh"] })`,
    `})`,
    ``
  ].join("\n")

// True for a target that declares its step's inputs in place of the whole repository.
const narrows = (target: StepTarget, narrowed: boolean): boolean =>
  narrowed && target.rule === "check" && target.inputs !== undefined

// The files a target declares. A setup target always runs, so it declares
// none: a dependency's key is part of a target's key, and a setup target that
// declared the repository would rerun every target after it on any change.
// What a later target reads of a setup step's work is in that target's own
// inputs. Any other target declares its step's inputs, or the whole
// repository when the step names none.
const filesOf = (target: StepTarget, narrowed: boolean): ReadonlyArray<string> => {
  if (target.rule === "setup") return []
  return narrows(target, narrowed)
    ? (target.inputs as ReadonlyArray<string>).map((input) => `S.glob(${text(`//${input}`)})`)
    : ["repository"]
}

const renderTarget = (
  target: StepTarget,
  index: number,
  variables: ReadonlyMap<string, string>,
  narrowed: boolean
): string => {
  const data = [...filesOf(target, narrowed), ...target.dependencies.map((label) => variables.get(label) as string)]
  const fields = [
    `shell: ${text(target.script)}`,
    ...(target.rule === "setup"
      ? [`outFiles: [${text(`//${markerDirectory}/${target.label}`)}]`, `cache: false`]
      : []),
    ...(Object.keys(target.env).length === 0 ? [] : [`env: ${JSON.stringify(target.env)}`]),
    ...(target.inheritEnv.length === 0 ? [] : [`inheritEnv: ${JSON.stringify(target.inheritEnv)}`]),
    ...(target.host === undefined ? [] : [`hosts: [${text(target.host)}]`]),
    // A target that declares what it reads is held to it: a read outside its
    // inputs fails the target instead of passing on a stale result. The
    // network stays open, as it is for the step in the original CI.
    `sandbox: ${narrows(target, narrowed) ? "{ network: true }" : text("none")}`,
    `timeout: ${text(stepTimeout)}`,
    `data: [${data.join(", ")}]`
  ]
  return [
    comment(target.title),
    `const step${index} = S.Shell.${target.rule === "setup" ? "Build" : "Test"}({`,
    fields.map((field) => `  ${field}`).join(",\n"),
    `})`,
    ``
  ].join("\n")
}

const renderPackage = (plan: StepPlan, narrowed: boolean): string => {
  const shared = plan.targets.length > sharedInputsAbove
  const variables = new Map(plan.targets.map((target, index) => [target.label, `step${index}`]))
  return [
    comment(generated),
    ...(plan.notes.length === 0 ? [] : [comment(`Not reproduced from the original CI: see ${notesPath}`)]),
    `import { Smithers as S } from "@smthrs/targets"`,
    ``,
    comment("A step can read any file, so a target declares the whole repository unless its step names what it reads."),
    comment("A setup target always runs and declares no files."),
    `const repository = ${shared ? `S.Filegroup({ srcs: [S.glob("//**")] })` : `S.glob("//**")`}`,
    ``,
    ...plan.targets.map((target, index) => renderTarget(target, index, variables, narrowed)),
    `export const Package = S.Package({`,
    `  targets: {`,
    [
      ...(shared ? [`    ${text(repositoryLabel)}: repository`] : []),
      ...plan.targets.map((target, index) => `    ${text(target.label)}: step${index}`)
    ].join(",\n"),
    `  }`,
    `})`,
    ``
  ].join("\n")
}

const byNameThenSource = (left: Toolchain, right: Toolchain): number =>
  `${left.name}\n${left.source}` < `${right.name}\n${right.source}` ? -1 : 1

const renderSetup = (toolchain: Toolchain): ReadonlyArray<string> => {
  const action = setupActions.get(toolchain.name)
  if (action === undefined) {
    return [`      ${yamlComment(`${toolchain.name} (${toolchain.source}) has no known setup action.`)}`]
  }
  return [
    `      - uses: ${action.uses}`,
    ...(toolchain.version === undefined
      ? []
      : [`        with:`, `          ${action.input}: ${text(toolchain.version)}`])
  ]
}

const renderWorkflow = (inventory: Inventory, plan: StepPlan, cache: string | undefined): string => {
  const toolchains = new Map<string, Toolchain>()
  for (const toolchain of [...inventory.toolchains].sort(byNameThenSource)) {
    if (!toolchains.has(toolchain.name)) toolchains.set(toolchain.name, toolchain)
  }
  const hasNode = toolchains.has("node")
  return [
    yamlComment(generated),
    `name: Smithers CI`,
    `on:`,
    ...plan.triggers.map((trigger) => `  ${trigger}:`),
    `permissions:`,
    `  contents: read`,
    `jobs:`,
    `  ci:`,
    `    strategy:`,
    `      fail-fast: false`,
    `      matrix:`,
    `        os: [${plan.runners.map(text).join(", ")}]`,
    `    runs-on: \${{ matrix.os }}`,
    `    steps:`,
    `      - uses: actions/checkout@v4`,
    ...(hasNode ? [] : [`      - uses: actions/setup-node@v4`, `        with:`, `          node-version: "24"`]),
    ...[...toolchains.values()].flatMap(renderSetup),
    `      ${yamlComment("Unconfined results never reach a remote cache, so the runner keeps its own.")}`,
    `      - uses: actions/cache@v4`,
    `        with:`,
    `          path: .flows/cache`,
    `          key: smithers-ci-\${{ matrix.os }}-\${{ github.sha }}`,
    `          restore-keys: smithers-ci-\${{ matrix.os }}-`,
    `      ${yamlComment("Targets share one working tree, so they run one at a time.")}`,
    `      - run: npx --yes --package=@smthrs/cli@next smthrs ci '//...' --jobs 1`,
    ...(cache === undefined ? [] : [
      `        env:`,
      `          SMITHERS_CACHE_URL: ${text(cache)}`,
      `          SMITHERS_CACHE_TOKEN: \${{ secrets.SMITHERS_CACHE_TOKEN }}`
    ]),
    ``
  ].join("\n")
}

/**
 * The target map (contract 11): the label a run record reports for each
 * step. Targets share one working tree, so at most one runs at a time.
 */
const renderTargetMap = (plan: StepPlan): string => {
  const map: TargetMap = {
    version: 1,
    targets: plan.targets.map((target) => ({
      label: `//:${target.label}`,
      job: target.job,
      step: target.step,
      variant: target.variant
    })),
    maxJobs: 1
  }
  return `${JSON.stringify(map, undefined, 2)}\n`
}

const renderNotes = (plan: StepPlan): string =>
  [
    `# Not reproduced from the original CI`,
    ``,
    generated,
    ``,
    ...plan.notes.map((note) => `- ${note.replace(/[\r\n\u2028\u2029]+/g, " ")}`),
    ``
  ].join("\n")

/**
 * Renders the workspace, the targets, the target map and the workflow. With
 * `options.cache`, the workflow sends results to that shared cache.
 *
 * A target declares its step's inputs and runs confined to them. When that
 * makes the targets too large for one `PACKAGE.ts`, every target declares the
 * whole repository instead, which reruns more and is never wrong. Fails when
 * the targets still do not fit.
 *
 * @throws {never}
 * @category rendering
 * @since 0.1.0
 */
export const renderFiles = (
  inventory: Inventory,
  plan: StepPlan,
  options?: GenerateOptions
): Result.Result<ReadonlyArray<GeneratedFile>, Failure> => {
  const fits = (content: string): boolean => new TextEncoder().encode(content).length <= maximumPackageBytes
  const narrowed = renderPackage(plan, true)
  const targets = fits(narrowed) ? narrowed : renderPackage(plan, false)
  if (!fits(targets)) {
    return Result.fail({
      code: "unsupported",
      message: `The generated targets exceed the ${maximumPackageBytes} bytes Smithers reads from a PACKAGE.ts.`,
      part: "generate"
    })
  }
  return Result.succeed([
    { path: workflowPath, content: renderWorkflow(inventory, plan, options?.cache) },
    { path: workspacePath, content: renderWorkspace(inventory) },
    { path: packagePath, content: targets },
    { path: targetMapPath, content: renderTargetMap(plan) },
    ...(plan.notes.length === 0 ? [] : [{ path: notesPath, content: renderNotes(plan) }])
  ])
}
